extensibilityCode.react:
// Slider controlado com formatador de valor
const [value, setValue] = useState([50]);

<div className="nds-stack" data-spacing="sm">
  <div className="nds-cluster" data-align="center" data-justify="between">
    <Label>Volume</Label>
    <span aria-live="polite" className="nds-text-body nds-tabular-nums">{value[0]}%</span>
  </div>
  <Slider
    value={value}
    onValueChange={setValue}
    min={0}
    max={100}
    step={1}
    aria-label="Volume"
  />
</div>

customizationCode.web:
/* Preenchimento em outra cor semântica */
.slider-sucesso .nds-slider-range {
  background-color: hsl(var(--success));
}

/* A borda e o miolo ficam no ::before — é ele que desenha a alça.
   A caixa de .nds-slider-thumb é o alvo de toque, e é transparente. */
.slider-sucesso .nds-slider-thumb::before {
  border-color: hsl(var(--success));
}

